/** normalise: lowercase, fold accents, strip punctuation, single-space runs */
function normalizeName(team: string): string {
  return team
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

const ALIAS_INDEX: Record<string, string> = Object.fromEntries(
  Object.entries(TEAM_ALIASES).map(([name, key]) => [normalizeName(name), key])
);

const STEM_INDEX: Map<string, string[]> = (() => {
  const index = new Map<string, string[]>();
  for (const key of Object.keys(TEAM_LOGOS)) {
    const stem = key.replace(/^[^/]+\//, "");
    const stems = index.get(stem) ?? [];
    stems.push(key);
    index.set(stem, stems);
  }
  return index;
})();

/**
 * Resolve a team name (season-file short name, bookmaker name, anything close)
 * to a public logo path, or undefined when no crest exists for the club.
 */
export function getLogo(team: string): string | undefined {
  if (!team) return undefined;
  const normalized = normalizeName(team);
  const aliased = ALIAS_INDEX[normalized];
  if (aliased !== undefined) return TEAM_LOGOS[aliased];
  // fall back to an unambiguous stem match, e.g. "Ajax" -> "eredivisie/ajax"
  const stems = STEM_INDEX.get(normalized.replace(/ /g, "_"));
  return stems !== undefined && stems.length === 1 ? TEAM_LOGOS[stems[0]] : undefined;
}
